@using sv_f8aca159531a4aeea82dbebe22df05b5.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService State

<div class="warehouse-selector">
    <label class="form-label mb-0 small text-white-50">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@State.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += StateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        State.CurrentWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    private void StateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        State.OnWarehouseChanged -= StateChanged;
    }
}

@using sv_f8aca159531a4aeea82dbebe22df05b5.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService State

<span class="alert-badge" title="Low-stock items">
    @if (State.LowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@State.LowStockCount</span>
    }
    else
    {
        <span class="badge bg-secondary rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        State.OnAlertCountChanged += StateChanged;
        State.OnWarehouseChanged += StateChanged;
    }

    private void StateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        State.OnAlertCountChanged -= StateChanged;
        State.OnWarehouseChanged -= StateChanged;
    }
}

