@page "/dashboard"
@using sv_f8aca159531a4aeea82dbebe22df05b5.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService State
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="card-text fs-5 fw-bold">@GetWarehouseName()</p>
                <p class="text-muted small">ID: @State.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card @(State.LowStockCount > 5 ? "border-danger" : "")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-2 fw-bold @(State.LowStockCount > 5 ? "text-danger" : "text-warning")">
                    @State.LowStockCount
                </p>
                <p class="text-muted small">Items below minimum level</p>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    @if (_isPolling)
                    {
                        <span class="badge bg-success">Active – every 10s</span>
                    }
                    else
                    {
                        <span class="badge bg-secondary">Stopped</span>
                    }
                </p>
                <p class="text-muted small">Last check: @_lastPollTime?.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <h5>Poll Log</h5>
    <ul class="list-group list-group-flush" style="max-height: 200px; overflow-y: auto;">
        @foreach (var entry in _pollLog.AsEnumerable().Reverse())
        {
            <li class="list-group-item py-1 small">@entry</li>
        }
    </ul>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isPolling;
    private DateTime? _lastPollTime;
    private readonly List<string> _pollLog = new();

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += OnWarehouseChanged;
        State.OnAlertCountChanged += StateChanged;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        _isPolling = true;
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Initial poll immediately
        await PollOnceAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await PollOnceAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(State.CurrentWarehouseId);
        _lastPollTime = DateTime.Now;
        _pollLog.Add($"[{_lastPollTime:HH:mm:ss}] {State.CurrentWarehouseId}: {count} low-stock items");

        // Setting this property fires OnAlertCountChanged, notifying ALL subscribers
        State.LowStockCount = count;

        await InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse
        StartPolling();
        InvokeAsync(StateHasChanged);
    }

    private void StateChanged() => InvokeAsync(StateHasChanged);

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == State.CurrentWarehouseId).Name ?? "Unknown";
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _isPolling = false;
        State.OnWarehouseChanged -= OnWarehouseChanged;
        State.OnAlertCountChanged -= StateChanged;
    }
}

