        if (firstRender)
        {
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        _isPolling = true;
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Initial poll immediately
        await PollOnceAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await PollOnceAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(State.CurrentWarehouseId);
        _lastPollTime = DateTime.Now;
        _pollLog.Add($"[{_lastPollTime:HH:mm:ss}] {State.CurrentWarehouseId}: {count} low-stock items");

        // Setting this property fires OnAlertCountChanged, notifying ALL subscribers
        State.LowStockCount = count;

        await InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse
        StartPolling();
        InvokeAsync(StateHasChanged);
    }

    private void StateChanged() => InvokeAsync(StateHasChanged);

    private string GetWarehouseName()
    {
        return WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == State.CurrentWarehouseId).Name ?? "Unknown";
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _isPolling = false;
        State.OnWarehouseChanged -= OnWarehouseChanged;
        State.OnAlertCountChanged -= StateChanged;
    }
}

